import { test } from 'node:test';
import assert from 'node:assert/strict';
import createHost from '../build/host.gen.ts';

const view = (status: string, task0: string, task1: string, retried0 = false, retried1 = false) =>
  ({ status, task0, task1, retried0, retried1 });

test('initial state and start', async () => {
  const h: any = await createHost();
  assert.deepEqual(await h.run(), view('idle', 'idle', 'idle'));
  assert.deepEqual(await h.worker('worker0'), { status: 'idle' });
  assert.equal(await h.worker('nope'), null);
  assert.equal((await h.workDone('worker0')).ok, false);
  assert.equal((await h.cancel()).ok, false);
  assert.deepEqual(await h.start(), { ok: true });
  assert.equal((await h.start()).ok, false);
  assert.deepEqual(await h.run(), view('running', 'assigned', 'assigned'));
  const msgs = await h.inFlight();
  assert.equal(msgs.length, 2);
  assert.deepEqual(msgs.map((m: any) => [m.from, m.to, m.action, m.data]).sort(), [
    ['run', 'worker0', 'Assign', {}], ['run', 'worker1', 'Assign', {}],
  ]);
  await h.deliverAll();
  assert.deepEqual(await h.worker('worker1'), { status: 'busy' });
  assert.deepEqual(await h.workDone('worker0'), { ok: true });
  const r = await h.inFlight();
  assert.deepEqual(r.map((m: any) => [m.from, m.to, m.action, m.data]), [['worker0', 'run', 'Report', { task: 0, outcome: 'completed' }]]);
  await h.deliverAll();
  assert.deepEqual(await h.run(), view('running', 'completed', 'assigned'));
  await h.workDone('worker1');
  await h.deliverAll();
  assert.deepEqual(await h.run(), view('completed', 'completed', 'completed'));
  await h.__dispose();
});

test('cancel aborts only assigned tasks', async () => {
  const h: any = await createHost();
  await h.start();
  await h.deliverAll();
  await h.workFailed('worker0');
  await h.deliverAll(); // retried
  await h.workFailed('worker0');
  await h.deliverAll();
  assert.deepEqual(await h.cancel(), { ok: true });
  const msgs = await h.inFlight();
  assert.deepEqual(msgs.map((m: any) => [m.to, m.action]), [['worker1', 'Abort']]);
  await h.deliverAll();
  assert.deepEqual(await h.worker('worker1'), { status: 'idle' });
  assert.deepEqual(await h.run(), view('failed', 'failed', 'cancelled', true));
  await h.__dispose();
});

test('cancel with both busy', async () => {
  const h: any = await createHost();
  await h.start();
  await h.deliverAll();
  await h.cancel();
  assert.deepEqual(await h.run(), view('cancelling', 'assigned', 'assigned'));
  await h.workDone('worker0'); // races the abort
  await h.deliverAll();
  assert.deepEqual(await h.run(), view('cancelled', 'completed', 'cancelled'));
  await h.__dispose();
});

test('a first failure is retried, a second is recorded', async () => {
  const h: any = await createHost();
  await h.start();
  await h.deliverAll();
  await h.workFailed('worker0');
  const msgs = await h.inFlight();
  assert.deepEqual(msgs.map((m: any) => [m.to, m.action, m.data]), [['run', 'Report', { task: 0, outcome: 'failed' }]]);
  await h.deliver(msgs[0].id);
  assert.deepEqual(await h.run(), view('running', 'assigned', 'assigned', true));
  assert.deepEqual((await h.inFlight()).map((m: any) => [m.from, m.to, m.action]), [['run', 'worker0', 'Assign']]);
  await h.deliverAll();
  assert.deepEqual(await h.worker('worker0'), { status: 'busy' });
  await h.workFailed('worker0');
  await h.deliverAll();
  assert.deepEqual(await h.run(), view('running', 'failed', 'assigned', true));
  await h.workDone('worker1');
  await h.deliverAll();
  assert.deepEqual(await h.run(), view('failed', 'failed', 'completed', true));
  await h.__dispose();
});

test('a timeout fails the task and aborts its worker; its late report is ignored', async () => {
  const h: any = await createHost();
  assert.equal((await h.taskTimeout(0)).ok, false);
  await h.start();
  await h.deliverAll();
  assert.equal((await h.taskTimeout(2)).ok, false);
  await h.workDone('worker1'); // report in flight
  assert.deepEqual(await h.taskTimeout(0), { ok: true });
  assert.equal((await h.taskTimeout(0)).ok, false);
  assert.deepEqual(await h.run(), view('running', 'failed', 'assigned'));
  assert.deepEqual((await h.inFlight()).filter((m: any) => m.from === 'run').map((m: any) => [m.to, m.action]), [['worker0', 'Abort']]);
  await h.deliverAll();
  assert.deepEqual(await h.worker('worker0'), { status: 'idle' });
  assert.deepEqual(await h.run(), view('failed', 'failed', 'completed'));
  await h.__dispose();
});

test('a timeout of the last assigned task ends the run; a late report is ignored', async () => {
  const h: any = await createHost();
  await h.start();
  await h.deliverAll();
  await h.workDone('worker0');
  await h.deliverAll();
  await h.workDone('worker1'); // report in flight
  assert.deepEqual(await h.taskTimeout(1), { ok: true });
  assert.deepEqual(await h.run(), view('failed', 'completed', 'failed'));
  await h.deliverAll();
  assert.deepEqual(await h.run(), view('failed', 'completed', 'failed'));
  await h.__dispose();
});

test('a timeout while cancelling', async () => {
  const h: any = await createHost();
  await h.start();
  await h.deliverAll();
  await h.cancel();
  assert.deepEqual(await h.taskTimeout(1), { ok: true });
  await h.deliverAll();
  assert.deepEqual(await h.run(), view('failed', 'cancelled', 'failed'));
  await h.__dispose();
});

test('a failure while cancelling is not retried', async () => {
  const h: any = await createHost();
  await h.start();
  await h.deliverAll();
  await h.workFailed('worker0');
  await h.cancel();
  await h.deliverAll();
  assert.deepEqual(await h.run(), view('failed', 'failed', 'cancelled'));
  await h.__dispose();
});

